import React, { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import "react-toastify/dist/ReactToastify.css";
import "./register.css";
import { useAuth } from "../../../contexts/auth";
import Loading from "../../../components/loading/loading";
import { useGoogleLogin } from "@react-oauth/google";
import { FcGoogle } from 'react-icons/fc';
import { toast } from 'react-toastify';

const Register = () => {
  const [username, setUsername] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [errors, setErrors] = useState({});

  const { register,googleRegister, isLoadingRegister } = useAuth();
  const navigate = useNavigate();

  const validateUsername = (username) => {
    const regex = /^[a-zA-Z0-9]{4,}$/;
    return regex.test(username);
  };

  const validateEmail = (email) => {
    const regex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return regex.test(email);
  };

  const validatePassword = (password) => {
    return password.length >= 8;
  };

  const googleSignUp = useGoogleLogin({
    onSuccess: async (codeResponse) => {
      try {
        const result = await register('google', codeResponse.access_token);
        if (result?.success) {
          navigate("/");
        }
      } catch (error) {
        toast.error('Google registration failed');
      }
    },
    onError: () => toast.error('Google registration failed'),
    flow: 'implicit',
    popup: true,
    cookiePolicy: 'single_host_origin'  });
  
  const handleSubmit = async (e) => {
    e.preventDefault();
    if (validateForm()) {
      const result = await register('credentials', {
        name: username,
        email,
        password
      });
      if (result?.success) {
        navigate("/");
      }
    }
  };

  const validateForm = () => {
    const newErrors = {};

    if (!username) {
      newErrors.username = "Username is required";
    } else if (!validateUsername(username)) {
      newErrors.username =
        "Username must be at least 4 characters and contain no special characters";
    }

    if (!email) {
      newErrors.email = "Email is required";
    } else if (!validateEmail(email)) {
      newErrors.email = "Please enter a valid email";
    }

    if (!password) {
      newErrors.password = "Password is required";
    } else if (!validatePassword(password)) {
      newErrors.password = "Password must be at least 8 characters";
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  if(isLoadingRegister) return <Loading isVisible={isLoadingRegister} />;

  return (
    <div className="auth-container">
      <div className="auth-box">
        <h2>Create Account</h2>
        <form onSubmit={handleSubmit}>
          <div className="auth-form-group">
            <label htmlFor="username">Username</label>
            <input
              type="text"
              id="username"
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              placeholder="Enter your username"
              className={errors.username ? "error" : ""}
              required
            />
            {errors.username && (
              <span className="error-message">{errors.username}</span>
            )}
          </div>
          <div className="auth-form-group">
            <label htmlFor="email">Email</label>
            <input
              type="email"
              id="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              placeholder="Enter your email"
              className={errors.email ? "error" : ""}
              required
            />
            {errors.email && (
              <span className="error-message">{errors.email}</span>
            )}
          </div>
          <div className="auth-form-group">
            <label htmlFor="password">Password</label>
            <input
              type="password"
              id="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              placeholder="Enter your password"
              className={errors.password ? "error" : ""}
              required
            />
            {errors.password && (
              <span className="error-message">{errors.password}</span>
            )}
          </div>
          <div className="auth-redirect">
            Already have an account? <Link to="/login">Log in</Link>
          </div>
          <button
            type="submit"
            className="auth-submit-btn"
            disabled={isLoadingRegister}
          >
            {isLoadingRegister ? "Registering..." : "Register"}
          </button>
        </form>
        <div className="auth-divider">
          <span>OR</span>
        </div>
        <button
          type="button"
          onClick={() => googleSignUp()}
          className="google-auth-btn"
        >
          <FcGoogle size={20} />
          Sign up with Google
        </button>
      </div>
    </div>
  );
};

export default Register;
